components.css:
.ds-btn {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	gap: 8px;
	height: 48px;
	padding: 8px 16px;
	border: 0;
	border-radius: 8px;
	background: var(--color-primary);
	color: var(--color-onPrimary);
	font-family: var(--font-sans);
	font-size: 16px;
	font-weight: 500;
	line-height: 1.25;
	cursor: pointer;
	transition: filter 200ms cubic-bezier(0, 0, 0.2, 1), transform 200ms cubic-bezier(0, 0, 0.2, 1);
}
.ds-btn:hover { filter: brightness(1.1); }
.ds-btn:active { transform: scale(0.97); }
.ds-btn:focus-visible {
	outline: 2px solid color-mix(in srgb, var(--color-primary) 60%, transparent);
	outline-offset: 2px;
}

.ds-icon-btn {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	width: 40px;
	height: 40px;
	padding: 0;
	border: 0;
	border-radius: 9999px;
	background: var(--color-primary);
	color: var(--color-onPrimary);
	cursor: pointer;
	transition: filter 200ms cubic-bezier(0, 0, 0.2, 1);
}
.ds-icon-btn:hover { filter: brightness(1.1); }
.ds-icon-btn:focus-visible {
	outline: 2px solid color-mix(in srgb, var(--color-primary) 60%, transparent);
	outline-offset: 2px;
}

.ds-stream {
	display: flex;
	align-items: center;
	justify-content: center;
	gap: 8px;
	width: 100%;
	height: 56px;
	padding: 8px 16px;
	border: 0;
	border-radius: 8px;
	background: var(--color-surface);
	color: var(--color-onSurface);
	font-family: var(--font-sans);
	font-size: 16px;
	font-weight: 500;
	cursor: pointer;
	transition: transform 300ms cubic-bezier(0, 0, 0.2, 1);
}
.ds-stream:hover { transform: scale(0.97); }
.ds-stream:focus-visible {
	outline: 2px solid color-mix(in srgb, var(--color-primary) 60%, transparent);
	outline-offset: 2px;
}
.ds-stream-glyph { width: 16px; height: 16px; border-radius: 4px; }
.ds-stream-label { letter-spacing: 0.01em; }

.ds-badge {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	width: max-content;
	padding: 4px 10px;
	border-radius: 9999px;
	background: var(--color-surfaceVariant);
	color: var(--color-secondary);
	font-family: var(--font-mono);
	font-size: 12px;
	font-weight: 700;
	line-height: 1;
	white-space: nowrap;
}

.ds-row {
	display: flex;
	align-items: stretch;
	gap: 16px;
	height: 80px;
	color: var(--color-onBackground);
	text-decoration: none;
	transition: transform 300ms cubic-bezier(0, 0, 0.2, 1);
}
.ds-row:hover { transform: scale(0.98); }
.ds-row-art {
	flex: none;
	width: 80px;
	height: 80px;
	border-radius: 8px;
	background: linear-gradient(135deg, #3b4150 0%, #8d7c74 55%, #d9c6b6 100%);
}
.ds-row-text {
	display: flex;
	flex-direction: column;
	justify-content: center;
	gap: 2px;
	min-width: 0;
}
.ds-row-title {
	font-family: var(--font-sans2);
	font-size: 18px;
	font-weight: 500;
	line-height: 1.55;
	color: var(--color-onBackground);
}
.ds-row-sub {
	display: flex;
	align-items: center;
	gap: 8px;
	font-family: var(--font-sans);
	font-size: 14px;
	font-weight: 500;
	line-height: 1.43;
	color: var(--color-secondary);
}
.ds-row-badge {
	display: inline-flex;
	align-items: center;
	padding: 4px 10px;
	border-radius: 9999px;
	background: var(--color-surfaceVariant);
	color: var(--color-secondary);
	font-family: var(--font-mono);
	font-size: 12px;
	font-weight: 700;
	line-height: 1;
	white-space: nowrap;
}

.ds-card {
	display: flex;
	flex-direction: column;
	gap: 2px;
	max-width: 320px;
	padding: 16px;
	border-radius: 16px;
	background: var(--color-surface);
	color: var(--color-onSurface);
	text-decoration: none;
	transition: transform 300ms cubic-bezier(0, 0, 0.2, 1);
}
.ds-card:hover { transform: scale(0.98); }
.ds-card:focus-visible {
	outline: 2px solid color-mix(in srgb, var(--color-primary) 60%, transparent);
	outline-offset: 2px;
}
.ds-card-title {
	font-family: var(--font-sans2);
	font-size: 16px;
	font-weight: 600;
	line-height: 1.5;
}
.ds-card-text {
	font-family: var(--font-sans);
	font-size: 14px;
	font-weight: 500;
	line-height: 1.43;
	color: var(--color-secondary);
}

.ds-toggle {
	position: relative;
	display: inline-flex;
	align-items: center;
	padding: 2px;
	border: 1px solid color-mix(in srgb, var(--color-secondary) 25%, transparent);
	border-radius: 9999px;
	background: transparent;
	cursor: pointer;
	font-family: var(--font-mono);
	font-size: 10px;
	font-weight: 700;
	line-height: 1;
	transition: border-color 300ms cubic-bezier(0, 0, 0.2, 1);
}
.ds-toggle:hover { border-color: color-mix(in srgb, var(--color-secondary) 60%, transparent); }
.ds-toggle:focus-visible {
	outline: 2px solid color-mix(in srgb, var(--color-primary) 60%, transparent);
	outline-offset: 2px;
}
.ds-toggle-opt {
	position: relative;
	z-index: 1;
	display: flex;
	align-items: center;
	justify-content: center;
	width: 40px;
	height: 14px;
	color: var(--color-secondary);
}
.ds-toggle-on { color: var(--color-background); }
.ds-toggle-thumb {
	position: absolute;
	top: 2px;
	left: 2px;
	width: 40px;
	height: 14px;
	border-radius: 9999px;
	background: var(--color-secondary);
	transition: transform 300ms cubic-bezier(0, 0, 0.2, 1);
}

.ds-player {
	display: flex;
	align-items: center;
	gap: 16px;
	width: 100%;
	height: 56px;
	padding: 8px 24px 8px 8px;
	border-radius: 9999px;
	background: var(--color-surface);
}
.ds-player-btn {
	display: flex;
	align-items: center;
	justify-content: center;
	width: 40px;
	height: 40px;
	flex: none;
	border: 0;
	border-radius: 9999px;
	background: var(--color-primary);
	color: var(--color-onPrimary);
	cursor: pointer;
	transition: filter 200ms cubic-bezier(0, 0, 0.2, 1);
}
.ds-player-btn:hover { filter: brightness(1.1); }
.ds-player-time {
	width: 32px;
	text-align: center;
	font-family: var(--font-mono);
	font-size: 14px;
	font-weight: 700;
	color: var(--color-secondary);
	font-variant-numeric: tabular-nums;
}
.ds-player-track {
	position: relative;
	flex: 1;
	height: 4px;
	border-radius: 9999px;
	background: color-mix(in srgb, var(--color-secondary) 25%, transparent);
}
.ds-player-fill {
	position: absolute;
	top: 0;
	bottom: 0;
	left: 0;
	border-radius: 9999px;
	background: var(--color-primary);
}
.ds-player-thumb {
	position: absolute;
	top: 50%;
	width: 16px;
	height: 16px;
	margin-left: -8px;
	transform: translateY(-50%);
	border-radius: 9999px;
	background: var(--color-primary);
}

.ds-sheet {
	display: inline-flex;
	align-items: center;
	gap: 16px;
	padding: 8px 8px 8px 16px;
	border-radius: 9999px;
	background: var(--color-surface);
	box-shadow: 0 20px 25px -5px rgb(144 124 124 / 0.15), 0 8px 10px -6px rgb(144 124 124 / 0.15);
}
.ds-sheet-preview {
	font-size: 15px;
	letter-spacing: 2px;
	line-height: 1;
}
.ds-sheet-toggle {
	display: flex;
	align-items: center;
	justify-content: center;
	width: 40px;
	height: 40px;
	padding: 0;
	border: 0;
	border-radius: 9999px;
	background: var(--color-primary);
	color: var(--color-onPrimary);
	cursor: pointer;
	transition: filter 200ms cubic-bezier(0, 0, 0.2, 1);
}
.ds-sheet-toggle:hover { filter: brightness(1.1); }
.ds-sheet-toggle:focus-visible {
	outline: 2px solid color-mix(in srgb, var(--color-primary) 60%, transparent);
	outline-offset: 2px;
}
@media (prefers-color-scheme: dark) {
	.ds-sheet {
		box-shadow: 0 20px 25px -5px rgb(0 0 0 / 0.5), 0 8px 10px -6px rgb(0 0 0 / 0.5);
	}
}

.ds-select {
	position: relative;
	display: inline-flex;
	flex-direction: column;
	align-items: flex-start;
	gap: 8px;
}
.ds-select-trigger {
	display: flex;
	align-items: center;
	gap: 16px;
	padding: 8px 0;
	font-family: var(--font-sans);
	font-size: 16px;
	font-weight: 500;
	color: var(--color-secondary);
	cursor: pointer;
}
.ds-select-menu {
	display: flex;
	flex-direction: column;
	gap: 4px;
	padding: 8px;
	border-radius: 16px;
	background: var(--color-surface);
	box-shadow: 0 20px 25px -5px rgb(144 124 124 / 0.15), 0 8px 10px -6px rgb(144 124 124 / 0.15);
}
.ds-select-opt {
	padding: 8px 16px;
	border-radius: 6px;
	font-family: var(--font-sans);
	font-size: 16px;
	font-weight: 500;
	color: var(--color-onSurface);
	white-space: nowrap;
	transition: background-color 200ms cubic-bezier(0, 0, 0.2, 1);
}
.ds-select-opt:hover { background: color-mix(in srgb, var(--color-secondary) 10%, transparent); }
.ds-selected { background: color-mix(in srgb, var(--color-secondary) 10%, transparent); }
@media (prefers-color-scheme: dark) {
	.ds-select-menu {
		box-shadow: 0 20px 25px -5px rgb(0 0 0 / 0.5), 0 8px 10px -6px rgb(0 0 0 / 0.5);
	}
}
